module EasyCDR_Top (
  rxp_i,
  rxn_i,
  pll_clkin_i,
  pll_clkout0_i,
  pll_clkout1_i,
  pll_clkout2_i,
  pll_clkout3_i,
  pll_lock_i,
  share_clk0_o,
  share_clk1_o,
  share_clk2_o,
  share_clk3_o,
  share_clk4_o,
  share_reset_o,
  rstn_i,
  dout_en_o,
  align_flag_o,
  error_o,
  dout_o
)
;
input rxp_i;
input rxn_i;
input pll_clkin_i;
input pll_clkout0_i;
input pll_clkout1_i;
input pll_clkout2_i;
input pll_clkout3_i;
input pll_lock_i;
output share_clk0_o;
output share_clk1_o;
output share_clk2_o;
output share_clk3_o;
output share_clk4_o;
output share_reset_o;
input rstn_i;
output dout_en_o;
output align_flag_o;
output error_o;
output [9:0] dout_o;
wire VCC;
wire GND;
  \~easycdr.EasyCDR_Top  u_easycdr (
    .rxp_i(rxp_i),
    .rxn_i(rxn_i),
    .rstn_i(rstn_i),
    .pll_clkout0_i(pll_clkout0_i),
    .pll_clkout1_i(pll_clkout1_i),
    .pll_clkout2_i(pll_clkout2_i),
    .pll_clkout3_i(pll_clkout3_i),
    .pll_clkin_i(pll_clkin_i),
    .pll_lock_i(pll_lock_i),
    .share_clk0_o(share_clk0_o),
    .share_clk1_o(share_clk1_o),
    .share_clk2_o(share_clk2_o),
    .share_clk3_o(share_clk3_o),
    .share_clk4_o(share_clk4_o),
    .share_reset_o(share_reset_o),
    .dout_en_o(dout_en_o),
    .error_o(error_o),
    .align_flag_o(align_flag_o),
    .dout_o(dout_o[8:0])
);
  VCC VCC_cZ (
    .V(VCC)
);
  GND GND_cZ (
    .G(GND)
);
  GSR GSR (
    .GSRI(VCC) 
);
assign dout_o[9] = GND;
endmodule /* EasyCDR_Top */
